  if(before.state==='not_detected')throw Object.assign(Error('未检测到客户端命令。桌面客户端可使用 --client manual 获取接入参数。'),{code:'CLIENT_NOT_FOUND'});
  fs.mkdirSync(HOME,{recursive:true});
